INSERT INTO bridging.questions
SELECT * FROM json_populate_recordset(null::bridging.questions, '[{"id":"01a00459-8c14-7cd2-b241-27a307a25f99","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"F is inversely proportional to the square of d. Explain what happens to F when d is halved.","model_answer":"F becomes 4 times the original value.","explanation":"Since F is inversely proportional to d^2, halving d makes d^2 become one quarter of the original value. Therefore F becomes 4 times as large.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.564Z","updated_at":"2026-08-15T07:36:12.564Z"},{"id":"01a00459-8c28-7a53-b1de-56308e632bf5","topic_id":"019f9df7-a2a2-7899-9f80-1aed5da88c11","prompt":"In a cake recipe problem, a matrix product AB is used to combine ingredient amounts with the number of cakes baked. Explain what the entries of AB represent.","model_answer":"They represent the total amounts of each ingredient required.","explanation":"When a matrix of ingredient quantities per cake is multiplied by a matrix showing how many cakes are made, each entry in the product gives the total amount of a particular ingredient needed.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.584Z","updated_at":"2026-08-15T07:36:12.584Z"},{"id":"01a00459-8c3c-7f99-a598-2738e3fd3e42","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"Express 10 000 SGD in USD if the exchange rate is USD 1 = SGD x.","model_answer":"10000/x","explanation":"If 1 USD = x SGD, then the number of USD received for 10 000 SGD is 10 000 divided by x.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.604Z","updated_at":"2026-08-15T07:36:12.604Z"},{"id":"01a00459-8c50-79ba-ad59-2e502c606165","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"Two exchange rates are given: 1 USD = SGD x in 2023, and in 2022 the rate was SGD 0.030 less per USD. The difference in exchanging SGD 10 000 between the two years is USD 166. Write down the equation in x.","model_answer":"10000/x - 10000/(x - 0.030) = 166","explanation":"In 2023, 10 000 SGD gives 10000/x USD. In 2022, 10 000 SGD gives 10000/(x - 0.030) USD. Their difference is 166 USD, so 10000/x - 10000/(x - 0.030) = 166.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.624Z","updated_at":"2026-08-15T07:36:12.624Z"},{"id":"01a00459-8c78-7f7a-8cd5-4ec7c331a4f1","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"Show that (7n - 1)^2 - (n - 1)^2 is a multiple of 12 for all integer values of n.","model_answer":"12n(4n - 1)","explanation":"Use the difference of two squares: (7n - 1)^2 - (n - 1)^2 = [(7n - 1) + (n - 1)] [(7n - 1) - (n - 1)] = (8n - 2)(6n). This simplifies to 12n(4n - 1), which is always divisible by 12.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.664Z","updated_at":"2026-08-15T07:36:12.664Z"},{"id":"019f9e72-b6b5-78bc-9d44-95b008df431a","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Explain why x^2 - 10x + 7 has its minimum value when x = 5.","model_answer":"Because the squared term is smallest when x = 5.","explanation":"From x^2 - 10x + 7 = (x - 5)^2 - 18, the squared term (x - 5)^2 is always at least 0. It is smallest when x = 5, so the whole expression is minimum at x = 5.","difficulty":"Easy","metadata":{"tags":"algebra,quadratics,minimum-value","subtopic":"quadratic expressions","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.845Z","updated_at":"2026-07-26T12:42:25.845Z"},{"id":"019f9e72-b6b8-7861-a416-d5144be184bf","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"A shopkeeper makes a loss of 24% when selling an item for $136. Find the selling price needed to make a profit of 40%.","model_answer":"$250","explanation":"If $136 is 76% of the cost price, then cost price = 136 ÷ 0.76 = 178.947... For a 40% profit, selling price = 1.4 × 178.947... = 250. So the required selling price is $250.","difficulty":"Medium","metadata":{"tags":"percentages,profit-and-loss,money","subtopic":"profit and loss","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.848Z","updated_at":"2026-07-26T12:42:25.848Z"},{"id":"019f9e72-b6bb-7080-b66e-034f8986efeb","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"A bag contains yellow and blue balls in the ratio 1:4. Five yellow balls are removed and 10 blue balls are added. The new ratio becomes 1:6. Find the original number of yellow balls.","model_answer":"20","explanation":"Let the original numbers be x and 4x. After the change, they become x - 5 and 4x + 10. Given (x - 5)/(4x + 10) = 1/6. So 6x - 30 = 4x + 10, hence 2x = 40 and x = 20.","difficulty":"Medium","metadata":{"tags":"ratio,word-problem,algebra","subtopic":"changing ratios","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.850Z","updated_at":"2026-07-26T12:42:25.850Z"},{"id":"019f9e72-b6c3-7306-91ea-93021d2cea00","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Each term in a sequence is obtained by subtracting the same number from the previous term. The sequence is 78, a, b, c, 42, ... Find a, b and c.","model_answer":"a = 69, b = 60, c = 51","explanation":"There are 4 equal steps from 78 to 42, so the common difference is (42 - 78) ÷ 4 = -9. Therefore a = 69, b = 60 and c = 51.","difficulty":"Easy","metadata":{"tags":"algebra,sequences,arithmetic-progression","subtopic":"arithmetic sequences","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.859Z","updated_at":"2026-07-26T12:42:25.859Z"},{"id":"019f9e72-b6c5-7f54-b639-d7a7557042e9","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Write an expression in terms of n for the nth term of the sequence 78, 69, 60, 51, ...","model_answer":"87 - 9n","explanation":"The first term is 78 and the common difference is -9. So the nth term is 78 + (n - 1)(-9) = 87 - 9n.","difficulty":"Easy","metadata":{"tags":"algebra,sequences,nth-term","subtopic":"nth term","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.861Z","updated_at":"2026-07-26T12:42:25.861Z"},{"id":"019f9e72-b6ca-7903-9322-9edf29f8572c","topic_id":"019f9df7-a2a2-7888-aef2-fd58477eb864","prompt":"The universal set contains the integers from 1 to 15. Set A contains the perfect squares and set B contains the prime numbers. Find n(A ∪ B).","model_answer":"9","explanation":"A = {1, 4, 9}. B = {2, 3, 5, 7, 11, 13}. There is no overlap, so n(A ∪ B) = 3 + 6 = 9.","difficulty":"Easy","metadata":{"tags":"sets,union,number-of-elements","subtopic":"set operations","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.866Z","updated_at":"2026-07-26T12:42:25.866Z"},{"id":"019f9e72-b6cd-76b7-8761-7b183729226c","topic_id":"019f9df7-a2a2-7888-aef2-fd58477eb864","prompt":"The universal set contains the integers from 1 to 15. Set B contains the prime numbers. List the elements of B''.","model_answer":"{1, 4, 6, 8, 9, 10, 12, 14, 15}","explanation":"The primes from 1 to 15 are 2, 3, 5, 7, 11 and 13. The complement B'' contains all other integers in the universal set.","difficulty":"Easy","metadata":{"tags":"sets,complement,prime-numbers","subtopic":"complement of a set","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.869Z","updated_at":"2026-07-26T12:42:25.869Z"},{"id":"019f9e72-b6cf-7a9b-9f18-e58a5e6ec9c6","topic_id":"019f9df7-a2a2-7930-a717-cd252273c91f","prompt":"A cumulative frequency graph for 160 students shows the lower quartile at 56 marks and the upper quartile at 72 marks. Find the interquartile range.","model_answer":"16","explanation":"Interquartile range = upper quartile - lower quartile = 72 - 56 = 16.","difficulty":"Easy","metadata":{"tags":"data,statistics,cumulative-frequency","subtopic":"interquartile range","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.871Z","updated_at":"2026-07-26T12:42:25.871Z"},{"id":"019f9e72-b6d7-71fb-a11b-81d02558f9ed","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Write as a single fraction in its simplest form: 3/(x + 2) + 1/(x - 2).","model_answer":"(4x - 4)/(x^2 - 4)","explanation":"The common denominator is (x + 2)(x - 2) = x^2 - 4. The numerator becomes 3(x - 2) + (x + 2) = 4x - 4. So the single fraction is (4x - 4)/(x^2 - 4).","difficulty":"Medium","metadata":{"tags":"algebra,fractions,simplification","subtopic":"algebraic fractions","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.879Z","updated_at":"2026-07-26T12:42:25.879Z"},{"id":"019f9e72-b6d9-7ffe-bda0-9c483c9a0e0b","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Expand and simplify (2x - 5)(x + 4).","model_answer":"2x^2 + 3x - 20","explanation":"Multiply each term: 2x(x + 4) - 5(x + 4) = 2x^2 + 8x - 5x - 20 = 2x^2 + 3x - 20.","difficulty":"Easy","metadata":{"tags":"algebra,expansion,brackets","subtopic":"expansion","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.881Z","updated_at":"2026-07-26T12:42:25.881Z"}]'::json)
