INSERT INTO bridging.questions
SELECT * FROM json_populate_recordset(null::bridging.questions, '[{"id":"019fa42c-353f-74c4-9c9f-db38c7a48ecf","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"The first four terms of a sequence T_1, T_2, T_3, T_4, ... are given by:\nT_1 = 3(1) - 2 = 1\nT_2 = 3(2) + 1 = 7\nT_3 = 3(3) + 4 = 13\nT_4 = 3(4) + 7 = 19\n\n(a) Write down an expression for T_5.\n(b) Find an expression, in terms of n, for the n-th term T_n.\n(c) Evaluate T_{25}.\n(d) Explain why 304 cannot be a term in this sequence.","model_answer":"(a) T_5 = 3(5) + 10 = 25\n(b) T_n = 6n - 5\n(c) 145\n(d) Setting 6n - 5 = 304 gives n = 51.5, which is not an integer.","explanation":"(a) T_5 = 3(5) + 10 = 25.\n(b) Terms are 1, 7, 13, 19, ... with common difference 6. T_n = 6n - 5.\n(c) T_25 = 6(25) - 5 = 145.\n(d) 6n - 5 = 304 => 6n = 309 => n = 51.5. Since n must be a positive integer, 304 is not a term in the sequence (also, all terms in T_n are odd, whereas 304 is even).","difficulty":"Hard","metadata":{"tags":"sequences,nth term","subtopic":"sequences","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-27T15:23:08.479Z","updated_at":"2026-07-27T15:23:08.479Z"},{"id":"01a00459-8a73-7aba-b797-a6522fae2515","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Write x^2 - 10x + 7 in the form (x - a)^2 + b.","model_answer":"(x - 5)^2 - 18","explanation":"Complete the square: x^2 - 10x + 7 = (x^2 - 10x + 25) - 25 + 7 = (x - 5)^2 - 18.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.144Z","updated_at":"2026-08-15T07:36:12.144Z"},{"id":"01a00459-8a87-7d4f-9e67-1a70093813e2","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"A shirt costs £14.75 in one country. In another country, the same shirt costs $21.99. If the exchange rate is $1 = £0.73, calculate how much more the second price is than the first, in pounds.","model_answer":"£1.30","explanation":"Convert $21.99 to pounds: 21.99 × 0.73 = 16.0527. Subtract 14.75: 16.0527 - 14.75 = 1.3027. To the nearest penny, the difference is £1.30.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.167Z","updated_at":"2026-08-15T07:36:12.167Z"},{"id":"01a00459-8aac-7e3b-962b-55fd51c7fe7d","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Simplify 6a^5b^2 ÷ 3a^2b.","model_answer":"2a^3b","explanation":"Divide coefficients: 6 ÷ 3 = 2. Subtract the powers: a^(5-2) = a^3 and b^(2-1) = b. So the simplified form is 2a^3b.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.204Z","updated_at":"2026-08-15T07:36:12.204Z"},{"id":"01a00459-8ac0-78dc-b100-100cc1a63716","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Use the laws of indices to find the value of k if 2^k × 2^4 = 64.","model_answer":"2","explanation":"Combine the powers: 2^(k+4) = 64. Since 64 = 2^6, we get k + 4 = 6. Therefore k = 2.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.224Z","updated_at":"2026-08-15T07:36:12.224Z"},{"id":"01a00459-8ad4-7bcd-8a6b-a92c5be59534","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"A number p has exactly 12 factors. Two of its factors are 4 and 15. Find one possible value of p.","model_answer":"60","explanation":"The number must be divisible by both 4 and 15, so it must be a multiple of 60. Now 60 = 2^2 × 3 × 5, so the number of factors is (2+1)(1+1)(1+1) = 12. Therefore one possible value is 60.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.244Z","updated_at":"2026-08-15T07:36:12.244Z"},{"id":"01a00459-8ae8-7a2e-bc34-7472bf448a72","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"Express 840 as a product of prime factors.","model_answer":"2^3 × 3 × 5 × 7","explanation":"840 = 84 × 10 = (2^2 × 3 × 7) × (2 × 5) = 2^3 × 3 × 5 × 7.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.264Z","updated_at":"2026-08-15T07:36:12.264Z"},{"id":"01a00459-8afc-7f0a-a5bd-9887c9c91c27","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"The least common multiple of 12, x and 28 is 420. Find two possible values of x between 12 and 100.","model_answer":"15 and 35","explanation":"420 = 2^2 × 3 × 5 × 7. Since 12 = 2^2 × 3 and 28 = 2^2 × 7, x must contribute a factor of 5 without creating higher powers that change the LCM. Two possible values are 15 and 35.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.284Z","updated_at":"2026-08-15T07:36:12.284Z"},{"id":"01a00459-8b10-7d45-abfc-6e190508e230","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Jessica invests $4540 at a rate of r% per year compound interest. At the end of 10 years, she has earned $1328.54 in interest. Find the value of r.","model_answer":"2.5%","explanation":"Final amount = 4540 + 1328.54 = 5868.54. So 4540(1 + r/100)^10 = 5868.54. Divide by 4540 to get (1 + r/100)^10 = 1.292. Taking the 10th root gives 1 + r/100 ≈ 1.025. Therefore r = 2.5%.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.304Z","updated_at":"2026-08-15T07:36:12.304Z"},{"id":"01a00459-8b24-7c99-9b9d-7c50ce636dc3","topic_id":"019f9df7-a2a2-7865-ab8c-df9bc214c173","prompt":"A regular polygon has interior angle to exterior angle ratio 5:4. Explain why this is impossible.","model_answer":"The number of sides is not a whole number.","explanation":"Let the interior angle be 5x and the exterior angle be 4x. Since they add up to 180°, 9x = 180, so x = 20 and the exterior angle is 80°. The number of sides would be 360 ÷ 80 = 4.5, which is not an integer, so such a regular polygon is impossible.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.324Z","updated_at":"2026-08-15T07:36:12.324Z"},{"id":"01a00459-8b38-79b0-8303-8496caf05eb0","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Explain why x^2 - 10x + 7 has its minimum value when x = 5.","model_answer":"Because the squared term is smallest when x = 5.","explanation":"From x^2 - 10x + 7 = (x - 5)^2 - 18, the squared term (x - 5)^2 is always at least 0. It is smallest when x = 5, so the whole expression is minimum at x = 5.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.344Z","updated_at":"2026-08-15T07:36:12.344Z"},{"id":"01a00459-8b3d-7b79-801b-9988a68d5e8c","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"A shopkeeper makes a loss of 24% when selling an item for $136. Find the selling price needed to make a profit of 40%.","model_answer":"$250","explanation":"If $136 is 76% of the cost price, then cost price = 136 ÷ 0.76 = 178.947... For a 40% profit, selling price = 1.4 × 178.947... = 250. So the required selling price is $250.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.349Z","updated_at":"2026-08-15T07:36:12.349Z"},{"id":"01a00459-8b4d-7714-a444-3605890393d7","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"A bag contains yellow and blue balls in the ratio 1:4. Five yellow balls are removed and 10 blue balls are added. The new ratio becomes 1:6. Find the original number of yellow balls.","model_answer":"20","explanation":"Let the original numbers be x and 4x. After the change, they become x - 5 and 4x + 10. Given (x - 5)/(4x + 10) = 1/6. So 6x - 30 = 4x + 10, hence 2x = 40 and x = 20.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.365Z","updated_at":"2026-08-15T07:36:12.365Z"},{"id":"01a00459-8b63-7902-9655-cbd7c2196711","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Each term in a sequence is obtained by subtracting the same number from the previous term. The sequence is 78, a, b, c, 42, ... Find a, b and c.","model_answer":"a = 69, b = 60, c = 51","explanation":"There are 4 equal steps from 78 to 42, so the common difference is (42 - 78) ÷ 4 = -9. Therefore a = 69, b = 60 and c = 51.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.387Z","updated_at":"2026-08-15T07:36:12.387Z"},{"id":"01a00459-8b74-7d45-816f-ee81af7109da","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Write an expression in terms of n for the nth term of the sequence 78, 69, 60, 51, ...","model_answer":"87 - 9n","explanation":"The first term is 78 and the common difference is -9. So the nth term is 78 + (n - 1)(-9) = 87 - 9n.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.404Z","updated_at":"2026-08-15T07:36:12.404Z"}]'::json)
