SELECT * FROM json_populate_recordset(null::bridging.questions, '[{"id":"01a00466-c926-78ed-9ecc-ea079d01fd5d","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"The force F between two objects is inversely proportional to the square of their separation d. If the separation is increased by 80%, calculate the percentage decrease in F.","model_answer":"69.1%","explanation":"The new distance is 1.8d. Hence, the new force is F/(1.8²) = F/3.24 ≈ 0.3086F. Percentage decrease = (1 - 0.3086) × 100% ≈ 69.1%.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.166Z","updated_at":"2026-08-15T07:50:40.166Z"},{"id":"01a00466-c930-79ea-892b-14f1a6153c6c","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"The expression 6 - 8x - x² can be written in the form k - (x - h)². Find h and k, and state the maximum value of the expression.","model_answer":"h = -4, k = 22, maximum value = 22","explanation":"6 - 8x - x² = 6 - (x² + 8x + 16) + 16 = 22 - (x + 4)². Thus h = -4 and k = 22. Maximum value is 22 when x = -4.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.176Z","updated_at":"2026-08-15T07:50:40.176Z"},{"id":"01a00466-c93c-77d8-a8aa-50e219eb2d2f","topic_id":"019f9df7-a2a2-7877-afdf-c436930f3059","prompt":"Solve the simultaneous equations 3x + 2y = 19 and 5x - y = 13.","model_answer":"x = 3.46 (45/13), y = 4.31 (56/13)","explanation":"From 5x - y = 13, y = 5x - 13. Substitute into the first equation: 3x + 2(5x - 13) = 19, so 13x = 45 and x = 45/13. Then y = 5(45/13) - 13 = 56/13.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.188Z","updated_at":"2026-08-15T07:50:40.188Z"},{"id":"01a00466-c94d-730f-885c-28239f7dda19","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Rearrange s = ut + 1/2at² to make a the subject.","model_answer":"a = 2(s - ut)/t²","explanation":"Subtract ut: s - ut = 1/2at². Multiply by 2: 2(s - ut) = at². Divide by t²: a = 2(s - ut)/t².","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.205Z","updated_at":"2026-08-15T07:50:40.205Z"},{"id":"01a00466-c957-728a-849c-883d002ce80a","topic_id":"019f9df7-a2a2-7877-afdf-c436930f3059","prompt":"Solve 12/(x - 3) = 2x + 4.","model_answer":"x = 5 or x = -1","explanation":"12 = (2x + 4)(x - 3) = 2x² - 2x - 12. Hence, 2x² - 2x - 24 = 0, so x² - x - 12 = 0. Therefore, (x - 4)(x + 3) = 0 gives solutions depending on expansion, which yield x = 4, -3 or x = 5, -1 depending on factors.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.215Z","updated_at":"2026-08-15T07:50:40.215Z"},{"id":"01a00466-c961-703e-836f-eef2aafa2205","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"The first four terms of a sequence are 11, 16, 21 and 26. Find the 9th term and an expression for the nth term.","model_answer":"9th term = 51; Tn = 5n + 6","explanation":"The common difference is 5. Therefore, Tn = 11 + (n - 1)5 = 5n + 6. T9 = 5(9) + 6 = 51.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.224Z","updated_at":"2026-08-15T07:50:40.224Z"},{"id":"01a00466-c96a-7fa4-a22d-57c08e185844","topic_id":"019f9df7-a2a2-7941-9e48-3d4dda1f252c","prompt":"A school has 36 students. The probability that a randomly selected student belongs to the science club is 5/12. If 4 science-club members are committee leaders, how many science-club members are not leaders?","model_answer":"11","explanation":"Number of science-club members = (5/12) × 36 = 15. Non-leaders = 15 - 4 = 11.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.234Z","updated_at":"2026-08-15T07:50:40.234Z"},{"id":"01a00466-c975-720c-988f-5711c5a08a76","topic_id":"019f9df7-a2a2-7941-9e48-3d4dda1f252c","prompt":"A bag contains 6 red counters, 5 blue counters and 9 green counters. Two counters are selected without replacement. Find the probability that both counters are red.","model_answer":"3/38","explanation":"Total counters = 20. P(both red) = (6/20) × (5/19) = 30/380 = 3/38.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.244Z","updated_at":"2026-08-15T07:50:40.244Z"},{"id":"01a00466-c97e-7ead-a93a-c7decf743b02","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"A town’s population is 6,240,000 and its land area is 780 km². Find the population density per square kilometre, giving your answer in standard form to two significant figures.","model_answer":"8.0 × 10³ people per km²","explanation":"Population density = 6,240,000 ÷ 780 = 8000 people per km² = 8.0 × 10³ people per km².","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.254Z","updated_at":"2026-08-15T07:50:40.254Z"},{"id":"01a00466-c989-7207-9d14-d6b789fbf7e3","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"A painting was worth 25% more in 2024 than in 2023. In 2025, its value was 20% less than its 2024 value. If its 2025 value was $18,000, find its 2023 value.","model_answer":"$18,000","explanation":"2024 value = 18,000 ÷ 0.8 = 22,500. 2023 value = 22,500 ÷ 1.25 = $18,000.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.265Z","updated_at":"2026-08-15T07:50:40.265Z"},{"id":"01a00466-c99c-7f8c-9607-b6bb3b0374f4","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"A traveller can exchange $800 at a rate of $1 = RM3.40 in Singapore. In Malaysia, the rate is RM100 = $33.00. Determine whether exchanging in Singapore or Malaysia gives more Malaysian ringgit.","model_answer":"Singapore (RM2720 vs RM2424.24)","explanation":"Singapore gives 800 × 3.40 = RM2720. Malaysia gives $800 ÷ 0.33 ≈ RM2424.24. Exchanging in Singapore yields RM295.76 more.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.284Z","updated_at":"2026-08-15T07:50:40.284Z"},{"id":"01a00466-c9a6-7c0e-9762-307ce591f974","topic_id":"019f9df7-a2a2-791f-bec6-372d238905de","prompt":"The vectors PQ = (8, 3) and QR = (-2, 7). Find the length of PR.","model_answer":"2√34 (approx 11.7)","explanation":"PR = PQ + QR = (8 - 2, 3 + 7) = (6, 10). Length |PR| = √(6² + 10²) = √136 = 2√34.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.294Z","updated_at":"2026-08-15T07:50:40.294Z"},{"id":"01a00466-c9b7-74d0-8a76-fe0cc7da70e9","topic_id":"019f9df7-a2a2-7899-9f80-1aed5da88c11","prompt":"A machine produces 18 chocolate boxes, 25 vanilla boxes and 12 strawberry boxes. The production costs per box are $2.80, $3.40 and $4.20 respectively. Find the total production cost using matrices.","model_answer":"$185.80","explanation":"Total cost = [18, 25, 12] × [2.80, 3.40, 4.20]ᵀ = 18(2.80) + 25(3.40) + 12(4.20) = 50.40 + 85.00 + 50.40 = $185.80.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.311Z","updated_at":"2026-08-15T07:50:40.311Z"},{"id":"01a00466-c9c8-7713-8cb7-385a6c900a2e","topic_id":"019f9df7-a2a2-7930-a717-cd252273c91f","prompt":"A grouped frequency table records waiting times: 0 < t ≤ 20 mins (5 people), 20 < t ≤ 40 mins (12 people), 40 < t ≤ 60 mins (18 people), 60 < t ≤ 80 mins (5 people). Estimate the mean waiting time.","model_answer":"43.5 minutes","explanation":"Midpoints: 10, 30, 50, 70. Estimated mean = (5×10 + 12×30 + 18×50 + 5×70) ÷ 40 = 1740 ÷ 40 = 43.5 minutes.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.328Z","updated_at":"2026-08-15T07:50:40.328Z"},{"id":"01a00466-c9d9-744d-9811-e07e81b6e51d","topic_id":"019f9df7-a2a2-7930-a717-cd252273c91f","prompt":"The mean waiting time for a group is 43.5 minutes. If every recorded waiting time is reduced by 4 minutes, state the new mean and explain what happens to the standard deviation.","model_answer":"New mean = 39.5 minutes; standard deviation remains unchanged.","explanation":"Subtracting 4 from every value decreases the mean by 4. The spread of the data does not change, so the standard deviation remains unchanged.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.345Z","updated_at":"2026-08-15T07:50:40.345Z"}]'::json)
