SELECT * FROM json_populate_recordset(null::bridging.questions, '[{"id":"01a00466-c9ec-7e5f-8d36-255481374b5f","topic_id":"019f9df7-a2a2-7941-9e48-3d4dda1f252c","prompt":"A school has 50 students. The probability that a student joins the drama club is 0.44. Two students are selected without replacement. Find the probability that both selected students belong to the drama club.","model_answer":"33/175","explanation":"Drama students = 0.44 × 50 = 22. P(both) = (22/50) × (21/49) = 462/2450 = 33/175.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.364Z","updated_at":"2026-08-15T07:50:40.364Z"},{"id":"01a00466-c9f7-708a-be56-d22ad06ef1bb","topic_id":"019f9df7-a2a2-78fc-bd9e-a40e9b4f9363","prompt":"A car tyre has a rim diameter of 18 inches. The tyre width is 225 mm and its sidewall height is 55% of its width. Using 1 inch = 2.54 cm, find the circumference of the tyre in metres.","model_answer":"2.21 m","explanation":"Rim diameter = 18 × 2.54 = 45.72 cm. Sidewall = 0.55 × 22.5 = 12.375 cm. Total diameter = 45.72 + 2(12.375) = 70.47 cm = 0.7047 m. Circumference = π(0.7047) ≈ 2.21 m.","difficulty":"Hard","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.374Z","updated_at":"2026-08-15T07:50:40.374Z"},{"id":"01a00466-ca00-7139-9345-e75bcf2e1e3a","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"A test tube contains 12 bacteria initially, and the number doubles every day. Find the number of bacteria after 7 days.","model_answer":"1536","explanation":"Number after 7 days = 12 × 2⁷ = 12 × 128 = 1536.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.383Z","updated_at":"2026-08-15T07:50:40.383Z"},{"id":"01a00466-ca0a-7137-b6e0-4fd535d547e8","topic_id":"019f9df7-a2a2-78fc-bd9e-a40e9b4f9363","prompt":"A cylindrical pipe has radius 4 cm. Water flows through it at 1.5 metres per second for 10 minutes. Find the volume of water delivered, in litres.","model_answer":"4524 litres","explanation":"Area = π(4²) = 16π cm². Column length = 150 cm/s × 600 s = 90,000 cm. Volume = 16π × 90,000 = 1,440,000π cm³ = 1440π litres ≈ 4524 litres.","difficulty":"Hard","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.393Z","updated_at":"2026-08-15T07:50:40.393Z"},{"id":"01a00466-ca13-76f9-92b2-115a46d9a7da","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"A rectangular field has length 24 m and width 15 m. Its length is increased by 12% while its width is decreased by 10%. Find the percentage change in its area.","model_answer":"0.8% increase","explanation":"Multiplier for area = 1.12 × 0.90 = 1.008. Percentage change = (1.008 - 1) × 100% = +0.8%.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.403Z","updated_at":"2026-08-15T07:50:40.403Z"},{"id":"01a00466-ca1c-7d26-87fa-c271fc993d72","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"A deposit earns 3.5% compound interest per year. After 4 years, the total interest earned is $742. Find the initial deposit, correct to the nearest dollar.","model_answer":"$5030","explanation":"Interest = P[(1.035)⁴ - 1] = 742. P = 742 / [(1.035)⁴ - 1] ≈ 742 / 0.14752 ≈ $5030.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.412Z","updated_at":"2026-08-15T07:50:40.412Z"},{"id":"01a00466-ca26-7539-9d64-3dcb82394224","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"A car costs $72,000. A buyer pays a 25% downpayment and borrows the balance for 5 years at 2.8% simple interest per year. Find the total repayment on the loan.","model_answer":"$61,560","explanation":"Loan amount = 75% × 72,000 = $54,000. Interest = 54,000 × 0.028 × 5 = $7,560. Total repayment = 54,000 + 7,560 = $61,560.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.422Z","updated_at":"2026-08-15T07:50:40.422Z"},{"id":"01a00466-ca2f-7572-805f-0ecd5b58bf45","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"A shop buys an item for $240 and sells it for $306. Find the percentage profit.","model_answer":"27.5%","explanation":"Profit = 306 - 240 = $66. Percentage profit = (66 / 240) × 100% = 27.5%.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.431Z","updated_at":"2026-08-15T07:50:40.431Z"},{"id":"01a00466-ca38-7977-bfa6-3578c2d5c0c2","topic_id":"019f9df7-a2a2-78fc-bd9e-a40e9b4f9363","prompt":"A cuboid has volume 720 cm³ and a square base. The side length of its base is greater than 3 cm. Find the smallest possible integer height.","model_answer":"5 cm","explanation":"Square factors of 720 with side > 3 include 16 (s=4, h=45), 36 (s=6, h=20), and 144 (s=12, h=5). The smallest integer height is 5 cm.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.440Z","updated_at":"2026-08-15T07:50:40.440Z"},{"id":"01a00466-ca42-787f-a014-71d87a66447c","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"A town’s population increases from 240,000 to 264,000 over one year. Find the percentage increase.","model_answer":"10%","explanation":"Increase = 264,000 - 240,000 = 24,000. Percentage increase = (24,000 / 240,000) × 100% = 10%.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.450Z","updated_at":"2026-08-15T07:50:40.450Z"},{"id":"01a00466-ca51-7363-a8ab-b4fdd480ec1c","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"A quantity p is directly proportional to q³. If q increases by 50%, find the percentage increase in p.","model_answer":"237.5%","explanation":"New q = 1.5q. New p = (1.5)³ p = 3.375 p. Percentage increase = (3.375 - 1) × 100% = 237.5%.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.465Z","updated_at":"2026-08-15T07:50:40.465Z"},{"id":"01a00466-ca5a-7bf8-a767-fc94431569b2","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"A grass plant grows 85 picometres in 2 milliseconds. Estimate how far it grows in 1 second, giving the answer in metres in standard form.","model_answer":"4.25 × 10⁻⁸ m","explanation":"Growth in 1 s (1000 ms) = 85 × (1000 / 2) = 42,500 pm. In metres: 42,500 × 10⁻¹² = 4.25 × 10⁻⁸ m.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.474Z","updated_at":"2026-08-15T07:50:40.474Z"},{"id":"01a00466-ca65-701d-9d8a-47de94dacbed","topic_id":"019f9df7-a2a2-7877-afdf-c436930f3059","prompt":"Solve the compound inequality 4 - 3x < 2x + 9 < x + 15.","model_answer":"-1 < x < 6","explanation":"4 - 3x < 2x + 9 => 5x > -5 => x > -1. 2x + 9 < x + 15 => x < 6. Combining gives -1 < x < 6.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.484Z","updated_at":"2026-08-15T07:50:40.484Z"},{"id":"01a00466-ca6e-73ea-865b-a0a24f469cc1","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"The first four terms of a sequence are 3, 8, 15 and 24. Find an expression for the nth term and calculate the 10th term.","model_answer":"Tn = n² + 2n; T10 = 120","explanation":"Differences are 5, 7, 9 (second difference = 2). Formula is Tn = n² + 2n. For n = 10, T10 = 10² + 2(10) = 120.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.494Z","updated_at":"2026-08-15T07:50:40.494Z"},{"id":"01a00466-ca78-7f94-aa0b-a72a6e5d89e6","topic_id":"019f9df7-a2a2-7877-afdf-c436930f3059","prompt":"Solve the inequality 7 - 4x ≤ 2x + 19 and state the least integer solution.","model_answer":"x ≥ -2; least integer = -2","explanation":"7 - 4x ≤ 2x + 19 => -6x ≤ 12 => x ≥ -2. The least integer is -2.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.504Z","updated_at":"2026-08-15T07:50:40.504Z"}]'::json)
