SELECT * FROM json_populate_recordset(null::bridging.questions, '[{"id":"01a00466-ca8d-7201-bbd9-4643a396b59e","topic_id":"019f9df7-a2a2-7941-9e48-3d4dda1f252c","prompt":"The probability that a student is in a sports club is 0.4, and the probability that a student is a leader is 0.25. Explain why the probability of being in a sports club or being a leader cannot always be found by simply adding these two probabilities.","model_answer":"Because the two events can overlap (are not mutually exclusive), leading to double counting.","explanation":"P(A ∪ B) = P(A) + P(B) - P(A ∩ B). Simple addition is only valid when the events are mutually exclusive (no overlap).","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.525Z","updated_at":"2026-08-15T07:50:40.525Z"},{"id":"01a067f4-c2da-7a38-b20a-55284c39be05","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"Mrs Ram bought a washing machine for $390 during a sale. The shop was having a 35% discount on all appliances.\n\nFind the usual selling price of the washing machine before the sale.","model_answer":"$600","explanation":"After a 35% discount, the customer pays 65% of the usual price.\n65% of usual price = $390\nUsual price = 390 / 0.65 = $600.","difficulty":"Easy","metadata":{"tags":"sass-2022-p1,q1","subtopic":"Reverse percentages","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.047Z","updated_at":"2026-09-03T15:48:09.047Z"},{"id":"01a067f4-c2ed-734f-a965-803793bd5041","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"A light on a computer comes on for 26 700 microseconds. One microsecond is 10^-6 seconds.\n\nWork out the length of time, in seconds, that the light is on in standard form.","model_answer":"2.67 x 10^-2 s","explanation":"26 700 microseconds = 26 700 x 10^-6 s\n= 2.67 x 10^4 x 10^-6 s\n= 2.67 x 10^-2 s.","difficulty":"Easy","metadata":{"tags":"sass-2022-p1,q3a","subtopic":"Standard form","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.069Z","updated_at":"2026-09-03T15:48:09.069Z"},{"id":"01a067f4-c302-7a81-a885-9acb954dc9b5","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Explain why sqrt(3) is irrational.","model_answer":"sqrt(3) cannot be expressed as a fraction p/q where p and q are integers and q is not zero.","explanation":"An irrational number cannot be written in the form p/q in lowest terms. sqrt(3) is not a perfect square, so it is irrational.","difficulty":"Easy","metadata":{"tags":"sass-2022-p1,q3b","subtopic":"Irrational numbers","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.090Z","updated_at":"2026-09-03T15:48:09.090Z"},{"id":"01a067f4-c326-7bf3-b9bf-3ecfa07f2d07","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"The length of a road is 385 m. Maria runs along this road at an average speed of 3.9 m/s. This speed is correct to 1 decimal place.\n\nCalculate the greatest possible time taken by Maria.","model_answer":"100 s","explanation":"Greatest time uses the lower bound of speed.\nLower bound of 3.9 m/s (1 d.p.) = 3.85 m/s.\nTime = distance / speed = 385 / 3.85 = 100 s.","difficulty":"Medium","metadata":{"tags":"sass-2022-p1,q4","subtopic":"Upper and lower bounds","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.126Z","updated_at":"2026-09-03T15:48:09.126Z"},{"id":"01a067f4-c33d-74e1-aee0-bc7d2376fdeb","topic_id":"019f9df7-a2a2-7877-afdf-c436930f3059","prompt":"Solve the inequality\n\n2(5 - x) <= 3x < 37 - 5x.","model_answer":"2 <= x < 37/8","explanation":"Split the inequality:\n2(5 - x) <= 3x => 10 - 2x <= 3x => 10 <= 5x => x >= 2.\n3x < 37 - 5x => 8x < 37 => x < 37/8.\nSo 2 <= x < 37/8.","difficulty":"Medium","metadata":{"tags":"sass-2022-p1,q6a","subtopic":"Compound inequalities","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.149Z","updated_at":"2026-09-03T15:48:09.149Z"},{"id":"01a067f4-c351-7ac5-950d-270e9c29c7b2","topic_id":"019f9df7-a2a2-7877-afdf-c436930f3059","prompt":"Write down the largest integer x which satisfies the inequality\n\n2(5 - x) <= 3x < 37 - 5x.","model_answer":"4","explanation":"From 2 <= x < 37/8 (= 4.625), the integers are 2, 3 and 4.\nThe largest integer is 4.","difficulty":"Easy","metadata":{"tags":"sass-2022-p1,q6b","subtopic":"Compound inequalities","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.169Z","updated_at":"2026-09-03T15:48:09.169Z"},{"id":"01a067f4-c378-7a2f-8da9-5ca58ef6a638","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"p is proportional to q^3. It is known that p = 24 for a particular value of q.\n\nFind the value of p when this value of q is halved.","model_answer":"3","explanation":"p = kq^3, so 24 = kq^3.\nWhen q is halved: p = k(q/2)^3 = kq^3 / 8 = 24 / 8 = 3.","difficulty":"Medium","metadata":{"tags":"sass-2022-p1,q7a","subtopic":"Direct proportion","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.208Z","updated_at":"2026-09-03T15:48:09.208Z"},{"id":"01a067f4-c38d-7286-90b8-22b3b5d3db84","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"y is inversely proportional to x^2. y = 4 when x = 3.\n\nFind y when x = 10.","model_answer":"0.36","explanation":"y = k / x^2, so 4 = k / 9 and k = 36.\nWhen x = 10: y = 36 / 100 = 0.36.","difficulty":"Medium","metadata":{"tags":"sass-2022-p1,q7b","subtopic":"Inverse proportion","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.229Z","updated_at":"2026-09-03T15:48:09.229Z"},{"id":"01a067f4-c39e-7f07-914c-0e36425a8870","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"A map is drawn to a scale of 1 : 50 000.\n\nAn airport runway is represented by a line of length 4.6 cm on the map. Calculate the actual length of the runway, giving your answer in kilometres.","model_answer":"2.3 km","explanation":"1 cm on map = 50 000 cm = 0.5 km actual.\n4.6 cm on map = 4.6 x 0.5 = 2.3 km.","difficulty":"Easy","metadata":{"tags":"sass-2022-p1,q8a","subtopic":"Map scales","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.246Z","updated_at":"2026-09-03T15:48:09.246Z"},{"id":"01a067f4-c3b3-7187-9335-d7c82660dbb5","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"A map is drawn to a scale of 1 : 50 000.\n\nThe actual area of the airport is 3.5 km^2. Calculate the area on the map which represents the airport, giving your answer in square centimetres.","model_answer":"14 cm^2","explanation":"1 cm : 0.5 km, so 1 cm^2 : 0.25 km^2.\nArea on map = 3.5 / 0.25 = 14 cm^2.","difficulty":"Medium","metadata":{"tags":"sass-2022-p1,q8b","subtopic":"Map scales","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.266Z","updated_at":"2026-09-03T15:48:09.266Z"},{"id":"01a067f4-c3c9-7a9b-8a48-bc812e020bc7","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Express as a single fraction in its simplest form:\n\n2x/(x^2 - 4) + 5/(2 - x).","model_answer":"(-3x - 10)/[(x - 2)(x + 2)]","explanation":"2x/(x^2 - 4) + 5/(2 - x)\n= 2x/[(x - 2)(x + 2)] - 5/(x - 2)\n= [2x - 5(x + 2)] / [(x - 2)(x + 2)]\n= (-3x - 10) / [(x - 2)(x + 2)].","difficulty":"Medium","metadata":{"tags":"sass-2022-p1,q10","subtopic":"Algebraic fractions","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.289Z","updated_at":"2026-09-03T15:48:09.289Z"},{"id":"01a067f4-c3ee-7ff7-bd8f-d698d5146359","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Express 60 as the product of its prime factors.","model_answer":"2^2 x 3 x 5","explanation":"60 = 2 x 30 = 2 x 2 x 15 = 2^2 x 3 x 5.","difficulty":"Easy","metadata":{"tags":"sass-2022-p1,q11a","subtopic":"Prime factorisation","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.326Z","updated_at":"2026-09-03T15:48:09.326Z"},{"id":"01a067f4-c3f5-736f-8fa9-fa75061a06d5","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"A school buys packs of pens and packs of rulers. There are 60 pens in each pack of pens and 42 rulers in each pack of rulers. The school wants to buy exactly the same number of pens and rulers.\n\nWork out the smallest number of each pack the school should buy.","model_answer":"7 packs of pens, 10 packs of rulers","explanation":"Need LCM of 60 and 42.\n60 = 2^2 x 3 x 5, 42 = 2 x 3 x 7.\nLCM = 2^2 x 3 x 5 x 7 = 420.\nPacks of pens = 420 / 60 = 7.\nPacks of rulers = 420 / 42 = 10.","difficulty":"Medium","metadata":{"tags":"sass-2022-p1,q11b","subtopic":"LCM word problems","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.333Z","updated_at":"2026-09-03T15:48:09.333Z"},{"id":"01a067f4-c405-7b88-a3f5-34cd8f9924ee","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Factorise completely:\n\n3ab - 6ac + 4cd - 2bd.","model_answer":"(b - 2c)(3a - 2d)","explanation":"3ab - 6ac + 4cd - 2bd\n= 3a(b - 2c) + 2d(2c - b)\n= 3a(b - 2c) - 2d(b - 2c)\n= (b - 2c)(3a - 2d).","difficulty":"Medium","metadata":{"tags":"sass-2022-p1,q13a","subtopic":"Factorisation by grouping","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.349Z","updated_at":"2026-09-03T15:48:09.349Z"}]'::json)
