SELECT * FROM json_populate_recordset(null::bridging.questions, '[{"id":"01a067f4-c42b-70bd-ab2c-da030201338f","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Factorise completely:\n\ny^2 - 6xy + 5x^2.","model_answer":"(y - 5x)(y - x)","explanation":"Need two terms multiplying to 5x^2 and summing to -6xy.\n(y - 5x)(y - x) = y^2 - xy - 5xy + 5x^2 = y^2 - 6xy + 5x^2.","difficulty":"Medium","metadata":{"tags":"sass-2022-p1,q13b","subtopic":"Quadratic factorisation","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.386Z","updated_at":"2026-09-03T15:48:09.386Z"},{"id":"01a067f4-c43e-7f0e-a166-751a57b73288","topic_id":"019f9df7-a2a2-790d-b90f-3e453f40cd4c","prompt":"Show that the point (-1, 0.5) lies on the line 2y = 3x + 4.","model_answer":"Substituting x = -1 gives y = 0.5, so the point lies on the line.","explanation":"Substitute x = -1:\n2y = 3(-1) + 4 = 1\ny = 0.5.\nSo (-1, 0.5) satisfies the equation.","difficulty":"Easy","metadata":{"tags":"sass-2022-p1,q14ai","subtopic":"Points on a line","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.406Z","updated_at":"2026-09-03T15:48:09.406Z"},{"id":"01a067f4-c452-7f01-ab2f-da7a578d8ea2","topic_id":"019f9df7-a2a2-790d-b90f-3e453f40cd4c","prompt":"Find the coordinates of the y-intercept of the line 2y = 3x + 4.","model_answer":"(0, 2)","explanation":"2y = 3x + 4\ny = 1.5x + 2.\nWhen x = 0, y = 2.\nY-intercept is (0, 2).","difficulty":"Easy","metadata":{"tags":"sass-2022-p1,q14aii","subtopic":"y-intercept","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.426Z","updated_at":"2026-09-03T15:48:09.426Z"},{"id":"01a067f4-c458-7c57-a70b-d6b3ca1c1475","topic_id":"019f9df7-a2a2-790d-b90f-3e453f40cd4c","prompt":"A is the point (2, 4) and B is the point (m, n), where m and n are both positive integers less than 10. The gradient of the line AB is 2/3.\n\nFind the coordinates of one of the possible positions for B.","model_answer":"(5, 6) or (8, 8)","explanation":"(n - 4)/(m - 2) = 2/3.\nOne solution: n - 4 = 2 and m - 2 = 3, so B = (5, 6).\nAnother: n - 4 = 4 and m - 2 = 6, so B = (8, 8).","difficulty":"Medium","metadata":{"tags":"sass-2022-p1,q14b","subtopic":"Gradient","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.432Z","updated_at":"2026-09-03T15:48:09.432Z"},{"id":"01a067f4-c46a-74de-a142-698003260060","topic_id":"019f9df7-a2a2-78c7-aa4b-565799c65ce4","prompt":"Container A and container B are geometrically similar. The surface area of container A is 9/16 of the surface area of container B.\n\nContainer B has a diameter of 24 cm. Calculate the diameter of container A.","model_answer":"18 cm","explanation":"Area ratio A : B = 9 : 16, so linear ratio = sqrt(9/16) = 3/4.\nd_A / 24 = 3/4\n d_A = 18 cm.","difficulty":"Medium","metadata":{"tags":"sass-2022-p1,q15a","subtopic":"Similar solids","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.450Z","updated_at":"2026-09-03T15:48:09.450Z"},{"id":"01a067f4-c47a-79e1-b19e-1880bc368241","topic_id":"019f9df7-a2a2-78c7-aa4b-565799c65ce4","prompt":"Container A and container B are geometrically similar. The surface area of container A is 9/16 of the surface area of container B.\n\nEach container has chocolates in it. Container A costs $10.80. Calculate the cost of container B.","model_answer":"$25.60","explanation":"Linear ratio A : B = 3 : 4, so volume ratio = (3/4)^3 = 27/64.\nCost is proportional to volume, so Cost_B / 10.80 = 64/27.\nCost_B = 10.80 x 64/27 = $25.60.","difficulty":"Hard","metadata":{"tags":"sass-2022-p1,q15b","subtopic":"Similar solids","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.466Z","updated_at":"2026-09-03T15:48:09.466Z"},{"id":"01a067f4-c490-7bab-b1b4-782650c76086","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Given that (x^5 x x^0) / sqrt(x) = x^k, find k.","model_answer":"9/2","explanation":"x^5 x x^0 / x^(1/2) = x^(5 + 0 - 1/2) = x^(9/2).\nSo k = 9/2.","difficulty":"Easy","metadata":{"tags":"sass-2022-p1,q16a","subtopic":"Laws of indices","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.488Z","updated_at":"2026-09-03T15:48:09.488Z"},{"id":"01a067f4-c4a2-7c13-af13-7c7ff7f544e4","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Simplify, expressing your answer in positive index:\n\n(x^27 / 27)^(2/3).","model_answer":"x^18 / 9","explanation":"(x^27 / 27)^(2/3) = x^(27 x 2/3) / 27^(2/3)\n= x^18 / 9.","difficulty":"Medium","metadata":{"tags":"sass-2022-p1,q16bi","subtopic":"Laws of indices","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.506Z","updated_at":"2026-09-03T15:48:09.506Z"},{"id":"01a067f4-c4a7-7f51-9e97-0aea3be8db50","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Simplify, expressing your answer in positive index:\n\n(27/7) / (p^2 / 3)^(-1).","model_answer":"9p^2 / 7","explanation":"(p^2 / 3)^(-1) = 3 / p^2.\n(27/7) / (3 / p^2) = (27/7) x (p^2 / 3) = 9p^2 / 7.","difficulty":"Medium","metadata":{"tags":"sass-2022-p1,q16bii","subtopic":"Laws of indices","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.511Z","updated_at":"2026-09-03T15:48:09.511Z"},{"id":"01a067f4-c4cb-7039-9ab9-f4e865c3d2d8","topic_id":"019f9df7-a2a2-7930-a717-cd252273c91f","prompt":"The stem-and-leaf diagram shows the distribution of the lengths of fish caught by a fisherman. The numbers x and y are non-negative digits. The mode and range of the data are 24 cm and 22 cm respectively.\n\nStem | Leaf\n1 | x 4 5 7 8\n2 | 0 1 2 y 4 4 5 8\n3 | 0 0 3\nKey: 2|0 means 20 cm.\n\nFind the value of x and the value of y.","model_answer":"x = 1, y = 4","explanation":"Maximum value = 33 cm.\nRange = 22 cm, so minimum = 33 - 22 = 11 cm, hence x = 1.\nMode = 24 cm, so y = 4 (24 appears most often).","difficulty":"Medium","metadata":{"tags":"sass-2022-p1,q17a","subtopic":"Stem-and-leaf diagrams","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.546Z","updated_at":"2026-09-03T15:48:09.546Z"},{"id":"01a067f4-c4df-74a0-9f00-fae0a8bc1aec","topic_id":"019f9df7-a2a2-7941-9e48-3d4dda1f252c","prompt":"The stem-and-leaf data below has 16 fish lengths in total (with x = 1 and y = 4):\n\n11, 14, 15, 17, 18, 20, 21, 22, 24, 24, 24, 25, 28, 30, 30, 33 (all in cm).\n\nIf two of the fishes caught are selected at random, find the probability that at least one of them is longer than or equal to 25 cm.","model_answer":"13/24","explanation":"Fish shorter than 25 cm: 11 values.\nP(both < 25) = (11/16) x (10/15) = 11/24.\nP(at least one >= 25) = 1 - 11/24 = 13/24.","difficulty":"Medium","metadata":{"tags":"sass-2022-p1,q17b","subtopic":"Probability without replacement","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.567Z","updated_at":"2026-09-03T15:48:09.567Z"},{"id":"01a067f4-c4f3-7379-9dc7-91ee5eff2730","topic_id":"019f9df7-a2a2-7888-aef2-fd58477eb864","prompt":"E = {x : x is a positive integer, x <= 12}\nX = {x : x is a prime number}\nY = {x : x <= 6}\n\nFind X ∩ Y.","model_answer":"{2, 3, 5}","explanation":"Primes in E: {2, 3, 5, 7, 11}.\nY = {1, 2, 3, 4, 5, 6}.\nX ∩ Y = {2, 3, 5}.","difficulty":"Easy","metadata":{"tags":"sass-2022-p1,q18ai","subtopic":"Set intersection","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.587Z","updated_at":"2026-09-03T15:48:09.587Z"},{"id":"01a067f4-c51a-7e36-94fc-85b4652e57d2","topic_id":"019f9df7-a2a2-7941-9e48-3d4dda1f252c","prompt":"E = {x : x is a positive integer, x <= 12}\nX = {x : x is a prime number}\nY = {x : x <= 6}\n\nA number k is chosen at random from E. Find the probability that k is not in (X ∪ Y). Give your answer as a fraction in lowest terms.","model_answer":"1/3","explanation":"X ∪ Y = {1, 2, 3, 4, 5, 6, 7, 11}.\nElements not in X ∪ Y: {8, 9, 10, 12} — 4 outcomes out of 12.\nP = 4/12 = 1/3.","difficulty":"Easy","metadata":{"tags":"sass-2022-p1,q18aii","subtopic":"Set probability","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.626Z","updated_at":"2026-09-03T15:48:09.626Z"},{"id":"01a067f4-c52f-7039-9483-4a2097734f5e","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"Khalid has savings of $15 000 which he would like to deposit in a bank for 5 years. He is deciding between the schemes offered by two banks.\n\nBank A: Simple interest of 1.2% per annum.\nBank B: Compound interest compounded monthly at 0.85% per annum.\n\nWhich bank should he leave his money with? Explain briefly.","model_answer":"Bank A (interest about $900 vs about $651 from Bank B)","explanation":"Bank A interest = 15000 x 1.2 x 5 / 100 = $900.\nBank B amount = 15000(1 + 0.85/1200)^60 ≈ $15 651.\nBank B interest ≈ $651.\nBank A gives more interest, so choose Bank A.","difficulty":"Hard","metadata":{"tags":"sass-2022-p1,q21","subtopic":"Simple and compound interest","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.646Z","updated_at":"2026-09-03T15:48:09.646Z"},{"id":"01a067f4-c542-7e85-b45e-49aa8ecc47b4","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"The expression x^2 - 10x + 17 can be written in the form (x - 5)^2 + n.\n\nFind the value of n.","model_answer":"-8","explanation":"(x - 5)^2 + n = x^2 - 10x + 25 + n.\nCompare constant terms: 25 + n = 17, so n = -8.","difficulty":"Medium","metadata":{"tags":"sass-2022-p1,q22ai","subtopic":"Completing the square","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.666Z","updated_at":"2026-09-03T15:48:09.666Z"}]'::json)
ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions
SELECT * FROM json_populate_recordset(null::bridging.questions, '[{"id":"01a067f4-c556-7df5-a540-c4fbbca664f4","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"The expression x^2 - 10x + 17 can be written as (x - 5)^2 - 8.\n\nExplain why when x = 5, the expression x^2 - 10x + 17 has its minimum value.","model_answer":"(x - 5)^2 >= 0, so the expression is smallest when (x - 5)^2 = 0, i.e. when x = 5.","explanation":"x^2 - 10x + 17 = (x - 5)^2 - 8.\n(x - 5)^2 is never negative and is zero when x = 5.\nSo the minimum value occurs at x = 5.","difficulty":"Medium","metadata":{"tags":"sass-2022-p1,q22aii","subtopic":"Completing the square","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.686Z","updated_at":"2026-09-03T15:48:09.686Z"},{"id":"01a067f4-c55f-7541-8075-0740557034db","topic_id":"019f9df7-a2a2-7865-ab8c-df9bc214c173","prompt":"The curve y = (1 - x)(x + 4) passes through the x-axis at points A and B.\n\nFind the coordinates of A and of B.","model_answer":"A(-4, 0), B(1, 0)","explanation":"On the x-axis, y = 0:\n(1 - x)(x + 4) = 0\nx = 1 or x = -4.\nA(-4, 0) and B(1, 0).","difficulty":"Medium","metadata":{"tags":"sass-2022-p1,q22bi","subtopic":"Quadratic graphs","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.695Z","updated_at":"2026-09-03T15:48:09.695Z"},{"id":"01a067f4-c56d-774f-8106-d3490284a1d7","topic_id":"019f9df7-a2a2-7865-ab8c-df9bc214c173","prompt":"Write down the equation of the line of symmetry of the graph y = (1 - x)(x + 4).","model_answer":"x = -1.5","explanation":"Roots are x = -4 and x = 1.\nAxis of symmetry is midway: x = (-4 + 1)/2 = -1.5.","difficulty":"Easy","metadata":{"tags":"sass-2022-p1,q22bii","subtopic":"Line of symmetry","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.709Z","updated_at":"2026-09-03T15:48:09.709Z"},{"id":"01a067f4-c581-7d5e-926a-a04c1c4b3639","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"S = RV / (3V - 1)\n\nCalculate the value of S when R = 100 and V = -13.","model_answer":"32.5","explanation":"S = 100(-13) / [3(-13) - 1]\n= -1300 / (-40)\n= 32.5.","difficulty":"Easy","metadata":{"tags":"sass-2022-p2,q1ai","subtopic":"Substitution into formulae","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.729Z","updated_at":"2026-09-03T15:48:09.729Z"},{"id":"01a067f4-c595-7b20-98d0-f619d46d57d3","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"S = RV / (3V - 1)\n\nRearrange the formula to make V the subject.","model_answer":"V = S / (3S - R)","explanation":"S(3V - 1) = RV\n3SV - S = RV\n3SV - RV = S\nV(3S - R) = S\nV = S / (3S - R).","difficulty":"Hard","metadata":{"tags":"sass-2022-p2,q1aii","subtopic":"Changing the subject","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.749Z","updated_at":"2026-09-03T15:48:09.749Z"},{"id":"01a067f4-c5a6-7895-bcbb-6d23b21386a6","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Given that n is an integer and n > 1, decide whether each statement is true or false. If false, give a counter-example.\n\n(i) n^3 > 1\n(ii) 1/n > 1/n^2\n(iii) (n - 1)(n + 3) is always odd","model_answer":"(i) True (ii) True (iii) False; e.g. n = 3 gives (2)(6) = 12 which is even","explanation":"(i) For n > 1, n^3 > 1.\n(ii) For n > 1, 1/n > 1/n^2 since n > 1.\n(iii) When n = 3, (n - 1)(n + 3) = 2 x 6 = 12, which is even, so the statement is false.","difficulty":"Medium","metadata":{"tags":"sass-2022-p2,q1b","subtopic":"Number properties","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.766Z","updated_at":"2026-09-03T15:48:09.766Z"},{"id":"01a067f4-c5ac-76fe-b1d2-e52f68221658","topic_id":"019f9df7-a2a2-7877-afdf-c436930f3059","prompt":"Solve these simultaneous equations. You must show your working.\n\n(1/4)x + (3/5)y = -6\n3y = -4x + 3","model_answer":"x = 12, y = -15","explanation":"From (1): 5x + 12y = -120 ... (3)\nFrom (2): 4x + 3y = 3, so 12y = 12 - 16x ... (4)\nSubstitute (4) into (3):\n5x + 12 - 16x = -120\n-11x = -132\nx = 12.\n3y = 3 - 48 = -45, so y = -15.","difficulty":"Medium","metadata":{"tags":"sass-2022-p2,q1c","subtopic":"Simultaneous equations","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.772Z","updated_at":"2026-09-03T15:48:09.772Z"},{"id":"01a067f4-c5bb-79f8-9ece-28d63cb2fe1a","topic_id":"019f9df7-a2a2-7899-9f80-1aed5da88c11","prompt":"A gift shop sells two types of fruit hampers, A and B.\n\nHamper A: 3 apples, 4 oranges, 2 pears, 0 pineapples\nHamper B: 4 apples, 6 oranges, 5 pears, 1 pineapple\n\nThis is represented by P = [[3, 4, 2, 0], [4, 6, 5, 1]].\n\nThe cost price of an apple, orange, pear and pineapple are $0.50, $0.45, $0.60 and $1.80 respectively.\n\nWrite down a 4 x 1 matrix Q to represent the cost price of the fruits.","model_answer":"Q = [[0.50], [0.45], [0.60], [1.80]]","explanation":"Order the prices to match columns of P: apple, orange, pear, pineapple.","difficulty":"Easy","metadata":{"tags":"sass-2022-p2,q2a","subtopic":"Matrix representation","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.787Z","updated_at":"2026-09-03T15:48:09.787Z"},{"id":"01a067f4-c5d2-7002-91fe-b8c637c82dfa","topic_id":"019f9df7-a2a2-7899-9f80-1aed5da88c11","prompt":"Using P = [[3, 4, 2, 0], [4, 6, 5, 1]] and Q = [[0.50], [0.45], [0.60], [1.80]], calculate PQ.","model_answer":"PQ = [[4.50], [9.50]]","explanation":"Row 1: 3(0.50) + 4(0.45) + 2(0.60) + 0 = 4.50.\nRow 2: 4(0.50) + 6(0.45) + 5(0.60) + 1(1.80) = 9.50.","difficulty":"Medium","metadata":{"tags":"sass-2022-p2,q2b","subtopic":"Matrix multiplication","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.809Z","updated_at":"2026-09-03T15:48:09.809Z"},{"id":"01a067f4-c5e5-7a47-ace3-23cc1474bd28","topic_id":"019f9df7-a2a2-7899-9f80-1aed5da88c11","prompt":"PQ = [[4.50], [9.50]] where row 1 is Hamper A and row 2 is Hamper B.\n\nDescribe what is represented by the elements of PQ.","model_answer":"The total cost price of the fruits in Hamper A ($4.50) and in Hamper B ($9.50).","explanation":"Each element is the dot product of a hamper row with the fruit price column — the ingredient cost of that hamper.","difficulty":"Easy","metadata":{"tags":"sass-2022-p2,q2c","subtopic":"Matrix interpretation","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.829Z","updated_at":"2026-09-03T15:48:09.829Z"},{"id":"01a067f4-c60c-7bed-ae90-05e0001c375f","topic_id":"019f9df7-a2a2-7899-9f80-1aed5da88c11","prompt":"Given R = [30 20] and PQ = [[4.50], [9.50]], calculate RPQ.","model_answer":"(325)","explanation":"RPQ = 30(4.50) + 20(9.50) = 135 + 190 = 325.","difficulty":"Medium","metadata":{"tags":"sass-2022-p2,q2d","subtopic":"Matrix multiplication","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.868Z","updated_at":"2026-09-03T15:48:09.868Z"},{"id":"01a067f4-c620-7c61-af14-3089ba1cd22c","topic_id":"019f9df7-a2a2-7899-9f80-1aed5da88c11","prompt":"R = [30 20] and RPQ = (325).\n\nSuggest a meaning for the information represented by the matrix RPQ.","model_answer":"The total cost price of the fruits in 30 Hamper A and 20 Hamper B.","explanation":"R counts hampers sold; multiplying by PQ gives total fruit cost for that order mix.","difficulty":"Easy","metadata":{"tags":"sass-2022-p2,q2e","subtopic":"Matrix interpretation","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.888Z","updated_at":"2026-09-03T15:48:09.888Z"},{"id":"01a067f4-c634-72fc-a258-3b0597eb45b3","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Your class will sell 480 packets of sugar cookies. Each packet contains 6 cookies. One batch of the recipe makes 48 cookies and uses 350 g of flour.\n\nHow much flour does your class need? Give your answer in kilograms.","model_answer":"21 kg","explanation":"Total cookies = 480 x 6 = 2880.\nBatches needed = 2880 / 48 = 60.\nFlour = 60 x 350 g = 21 000 g = 21 kg.","difficulty":"Medium","metadata":{"tags":"sass-2022-p2,q11a","subtopic":"Ratio and unit conversion","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.908Z","updated_at":"2026-09-03T15:48:09.908Z"},{"id":"01a067f4-c649-7eff-9925-e4f6c4085aea","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"Your class needs 21 kg of flour. Prices (excluding 7% GST):\n\nSupermarket A: 454 g for $0.95; 1 kg for $1.85; 2 x 1 kg for $3.50.\nSupermarket B: 454 g for $0.90; 1 kg for $1.90; no multi-pack offer.\n\nWhich supermarket should your class buy the flour from? Show your calculations and reason clearly.","model_answer":"Supermarket A (cheapest unit price $1.75/kg with the 2-for-$3.50 offer)","explanation":"A: 454 g pack ≈ $2.09/kg; 1 kg = $1.85/kg; 2-for-$3.50 = $1.75/kg (best).\nB: 454 g ≈ $1.98/kg; 1 kg = $1.90/kg.\nLowest unit price is A''s 2-for-$3.50 offer, so buy flour from Supermarket A.","difficulty":"Medium","metadata":{"tags":"sass-2022-p2,q11b","subtopic":"Best buy","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.929Z","updated_at":"2026-09-03T15:48:09.929Z"},{"id":"01a067f4-c66e-7aff-881b-931aa62132b0","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"Your class will make 60 batches of sugar cookies (48 cookies per batch) and sell 480 packets (6 cookies per packet). They must cover all ingredient and packaging costs (prices excluding 7% GST below) and donate at least $1000 to charity.\n\nSupermarket A: flour 454g $0.95, 1kg $1.85, 2x1kg $3.50; baking soda 150g $0.80; butter 250g $4.80 (2 for $7.00); caster sugar 500g $1.65; eggs 10-pack $1.65; bags 100-pack $8.43.\n\nSupermarket B: flour 454g $0.90, 1kg $1.90; baking soda 150g $1.15; butter 250g $4.80 (buy 2 get $2.65 off, i.e. 2 for $6.95); caster sugar 500g $1.65; eggs 30-pack $3.85; bags 100-pack $7.15.\n\nPer batch: 350g flour, 7g baking soda, 130g butter, 300g caster sugar, 1 egg.\n\nSuggest a sensible selling price for one packet. Show working to justify your decision.","model_answer":"$3 per packet (minimum about $2.65 per packet after GST to cover costs and $1000 donation)","explanation":"Total ingredient masses for 60 batches: 21 kg flour, 420 g baking soda, 7800 g butter, 18 000 g sugar, 60 eggs, plus 480 bags.\nCheapest sourcing (from model answer): flour A, baking soda A, butter B, sugar either, eggs B, bags B.\nTotal cost after GST ≈ $271; with $1000 donation target, need about $1271 over 480 packets ≈ $2.65 each.\n$3 per packet is a sensible rounded price.","difficulty":"Hard","metadata":{"tags":"sass-2022-p2,q11c","subtopic":"Financial decision making","question_type":"open","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-09-03T15:48:09.966Z","updated_at":"2026-09-03T15:48:09.966Z"}]'::json)
